#include <vector>
#include <cstdint>

// Count tilings of n (rows) x m (columns) using 1x1 and 1x2 horizontal dominoes,
// with the requirement that every internal vertical boundary is crossed by at least one domino.
// Result modulo 1e9+7.
long long countNonBreakableTilings(int n, int m) {
    const long long MOD = 1000000007LL;
    if (m == 0) return 1; // empty board
    int S = 1 << n;
    
    // Build transition matrix B: B[prev][next] = 1 if (next & prev) == 0 and next != 0.
    std::vector<std::vector<long long>> B(S, std::vector<long long>(S, 0));
    for (int prev = 0; prev < S; ++prev) {
        for (int next = 0; next < S; ++next) {
            if (next != 0 && (next & prev) == 0) {
                B[prev][next] = 1;
            }
        }
    }
    
    // Matrix multiplication (modulo).
    auto matMul = [&](const std::vector<std::vector<long long>>& A,
                      const std::vector<std::vector<long long>>& C) {
        int sz = A.size();
        std::vector<std::vector<long long>> R(sz, std::vector<long long>(sz, 0));
        for (int i = 0; i < sz; ++i) {
            for (int k = 0; k < sz; ++k) {
                if (A[i][k] == 0) continue;
                for (int j = 0; j < sz; ++j) {
                    R[i][j] = (R[i][j] + A[i][k] * C[k][j]) % MOD;
                }
            }
        }
        return R;
    };
    
    // Identity matrix.
    std::vector<std::vector<long long>> I(S, std::vector<long long>(S, 0));
    for (int i = 0; i < S; ++i) I[i][i] = 1;
    
    // Matrix exponentiation B^(m-1).
    long long exp = m - 1;
    auto base = B;
    auto result = I;
    while (exp > 0) {
        if (exp & 1) result = matMul(result, base);
        base = matMul(base, base);
        exp >>= 1;
    }
    
    // Sum of first row of result: paths from mask 0 to any mask after m-1 internal boundaries.
    long long answer = 0;
    for (int j = 0; j < S; ++j) {
        answer = (answer + result[0][j]) % MOD;
    }
    return answer;
}

#include <cassert>

int main() {
    // Basic correctness checks for small n and m.
    assert(countNonBreakableTilings(1, 1) == 1);
    assert(countNonBreakableTilings(1, 2) == 1);
    assert(countNonBreakableTilings(1, 3) == 0);
    assert(countNonBreakableTilings(2, 2) == 3);
    assert(countNonBreakableTilings(2, 3) == 2);
    assert(countNonBreakableTilings(2, 4) == 2);
    assert(countNonBreakableTilings(3, 2) == 7);
    assert(countNonBreakableTilings(4, 2) == 15);
    // Large m should not overflow or crash.
    long long res = countNonBreakableTilings(6, 1000000000LL);
    assert(res >= 0);
    return 0;
}
